script:
(function () {
  'use strict';
  // Black-Scholes-Merton price of a European call and put on a stock paying a continuous dividend
  // yield q (time T in years = calendar days / 365):
  //   d1 = [ln(S/K) + (r - q + v^2/2) T] / (v sqrt(T)),  d2 = d1 - v sqrt(T)
  //   call = S e^(-qT) N(d1) - K e^(-rT) N(d2);  put = K e^(-rT) N(-d2) - S e^(-qT) N(-d1)
  // Greeks: delta, gamma, vega (per 1 percentage point of volatility = vega / 100), theta per
  // calendar day (annual theta / 365) and rho per 1 percentage point of rate (rho / 100).
  // N(x) uses Hart's double-precision algorithm (as published by G. West, 2005), absolute error below 1e-15.
  // Checked in Node (bs.test.js): N(x) matches Python's 0.5*erfc(-x/sqrt 2) to < 1e-14 from -10 to 9;
  // Hull, Options, Futures and Other Derivatives, example S=42, K=40, r=10%, v=20%, T=0.5:
  //   d1 = 0.7693, d2 = 0.6278, call = 4.76, put = 0.81;
  // Hull's Greeks example S=49, K=50, r=5%, v=20%, T=0.3846: call = 2.40, delta = 0.522,
  //   gamma = 0.066, theta = -4.31 a year (-0.0118 a day), vega = 12.1 (0.121 per 1%), rho = 8.91;
  // Hull's index-option example S=930, K=900, r=8%, q=3%, v=20%, T=2/12: call = 51.83;
  // put-call parity c - p = S e^(-qT) - K e^(-rT) holds to < 1e-12 on 1,000 random cases.
  var DAYS_PER_YEAR = 365;
  var OUTPUTS = ['bsCall', 'bsPut', 'bsD1', 'bsD2', 'bsNd1', 'bsNd2', 'bsYears', 'bsCallIntrinsic',
    'bsPutIntrinsic', 'bsCallTime', 'bsPutTime', 'bsParity'];

  // --- calc start
  function normCdf(x) {
    var a = Math.abs(x), c, e, b;
    if (a > 37) {
      c = 0;
    } else {
      e = Math.exp(-a * a / 2);
      if (a < 7.07106781186547) {
        b = 3.52624965998911e-2 * a + 0.700383064443688;
        b = b * a + 6.37396220353165;
        b = b * a + 33.912866078383;
        b = b * a + 112.079291497871;
        b = b * a + 221.213596169931;
        b = b * a + 220.206867912376;
        c = e * b;
        b = 8.83883476483184e-2 * a + 1.75566716318264;
        b = b * a + 16.064177579207;
        b = b * a + 86.7807322029461;
        b = b * a + 296.564248779674;
        b = b * a + 637.333633378831;
        b = b * a + 793.826512519948;
        b = b * a + 440.413735824752;
        c = c / b;
      } else {
        b = a + 0.65;
        b = a + 4 / b;
        b = a + 3 / b;
        b = a + 2 / b;
        b = a + 1 / b;
        c = e / b / 2.506628274631;
      }
    }
    return x > 0 ? 1 - c : c;
  }

  function normPdf(x) { return Math.exp(-x * x / 2) / Math.sqrt(2 * Math.PI); }

  // S, K > 0; T > 0 years; v > 0; r, q as decimals.
  function blackScholes(S, K, T, v, r, q) {
    var sq = Math.sqrt(T), vs = v * sq;
    var d1 = (Math.log(S / K) + (r - q + v * v / 2) * T) / vs, d2 = d1 - vs;
    var dq = Math.exp(-q * T), dr = Math.exp(-r * T);
    var Nd1 = normCdf(d1), Nd2 = normCdf(d2), Nmd1 = normCdf(-d1), Nmd2 = normCdf(-d2), pd1 = normPdf(d1);
    var decay = -S * dq * pd1 * v / (2 * sq);
    return {
      d1: d1, d2: d2, Nd1: Nd1, Nd2: Nd2,
      call: Math.max(0, S * dq * Nd1 - K * dr * Nd2),
      put: Math.max(0, K * dr * Nmd2 - S * dq * Nmd1),
      forwardGap: S * dq - K * dr,
      callDelta: dq * Nd1,
      putDelta: dq * (Nd1 - 1),
      gamma: dq * pd1 / (S * vs),
      vega: S * dq * pd1 * sq,
      callTheta: decay + q * S * dq * Nd1 - r * K * dr * Nd2,
      putTheta: decay - q * S * dq * Nmd1 + r * K * dr * Nmd2,
      callRho: K * T * dr * Nd2,
      putRho: -K * T * dr * Nmd2
    };
  }
  // --- calc end

  function el(id) { return document.getElementById(id); }
  function num(id) {
    var v = parseFloat(el(id).value);
    return isFinite(v) ? v : NaN;
  }
  function fix(x, dp) {
    if (!isFinite(x)) return '–';
    if (Math.abs(x) < 0.5 * Math.pow(10, -dp)) x = 0;
    return x.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp });
  }
  function usd(x) {
    var t = fix(x, 2);
    return t.charAt(0) === '-' ? '−$' + t.slice(1) : '$' + t;
  }
  function signed(x, dp) { return fix(x, dp).replace(/^-/, '−'); }

  function clear(msg) {
    var error = el('bsError');
    error.hidden = !msg;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { el(id).textContent = '–'; });
    el('bsGreeks').innerHTML = '';
  }

  function update() {
    var S = num('bsSpot'), K = num('bsStrike'), days = num('bsDays'), vol = num('bsVol'),
        rate = num('bsRate'), yld = num('bsYield');
    var msg = '';
    if (isNaN(S) || S <= 0 || S > 1e9) msg = 'Enter a stock price above $0.';
    else if (isNaN(K) || K <= 0 || K > 1e9) msg = 'Enter a strike price above $0.';
    else if (isNaN(days) || days < 1 || days > 10950) msg = 'Enter between 1 and 10,950 days to expiration.';
    else if (isNaN(vol) || vol <= 0 || vol > 500) msg = 'Enter a volatility above 0% and up to 500%.';
    else if (isNaN(rate) || rate < -10 || rate > 100) msg = 'Enter a risk-free rate from -10% to 100%.';
    else if (isNaN(yld) || yld < 0 || yld > 100) msg = 'Enter a dividend yield from 0% to 100%.';
    if (msg) { clear(msg); return; }
    clear('');

    var T = days / DAYS_PER_YEAR;
    var g = blackScholes(S, K, T, vol / 100, rate / 100, yld / 100);
    var callIntrinsic = Math.max(0, S - K), putIntrinsic = Math.max(0, K - S);
    el('bsCall').textContent = usd(g.call);
    el('bsPut').textContent = usd(g.put);
    el('bsD1').textContent = signed(g.d1, 4);
    el('bsD2').textContent = signed(g.d2, 4);
    el('bsNd1').textContent = fix(g.Nd1, 4);
    el('bsNd2').textContent = fix(g.Nd2, 4);
    el('bsYears').textContent = fix(T, 4) + ' years';
    el('bsCallIntrinsic').textContent = usd(callIntrinsic);
    el('bsPutIntrinsic').textContent = usd(putIntrinsic);
    el('bsCallTime').textContent = usd(g.call - callIntrinsic);
    el('bsPutTime').textContent = usd(g.put - putIntrinsic);
    el('bsParity').textContent = usd(g.call - g.put) + ' = ' + usd(g.forwardGap);

    var rows = [
      ['Delta', g.callDelta, g.putDelta, 4],
      ['Gamma', g.gamma, g.gamma, 4],
      ['Theta (per day)', g.callTheta / DAYS_PER_YEAR, g.putTheta / DAYS_PER_YEAR, 4],
      ['Vega (per 1% volatility)', g.vega / 100, g.vega / 100, 4],
      ['Rho (per 1% rate)', g.callRho / 100, g.putRho / 100, 4]
    ];
    el('bsGreeks').innerHTML = rows.map(function (r) {
      return '<tr><th scope="row">' + r[0] + '</th><td>' + signed(r[1], r[3]) + '</td><td>' + signed(r[2], r[3]) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('bsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
